using System;using System.IO;using System.Linq;using System.Reflection;using System.Threading.Tasks;using System.Windows.Forms;using Media=System.Windows.Controls.MediaElement;
static class PackagedPreviewChecks {
 static Assembly preview;
 static void Set(string name,object value){preview.GetType("PreviewProgram").GetField(name,BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,value);}
 static Form Capture(){return (Form)Activator.CreateInstance(preview.GetType("VideoPreview"),true);}
 static Form Quick(string clip){return (Form)Activator.CreateInstance(preview.GetType("QuickFilePreview"),BindingFlags.Instance|BindingFlags.NonPublic,null,new object[]{new[]{clip}},null);}
 static int checks;static T Field<T>(object o,string name){var field=o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic);return (T)(field!=null?field.GetValue(o):o.GetType().GetProperty(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o,null));}
 static void Check(bool result,string message){if(!result)throw new Exception(message);checks++;}
 static void Mouse(Control c,string method,int x){c.GetType().GetMethod(method,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(c,new object[]{new MouseEventArgs(MouseButtons.Left,1,x,c.Height/2,0)});}
 static async Task Until(Func<bool> test,string message){for(int i=0;i<60&&!test();i++)await Task.Delay(100);Check(test(),message);}
 static void NearEnd(Control slider){Mouse(slider,"OnMouseDown",(int)(slider.Width*.96));Mouse(slider,"OnMouseUp",(int)(slider.Width*.96));}
 static async Task Exercise(Form form,string kind){form.Show();await Until(()=>Field<Media>(form,"media")!=null&&Field<Media>(form,"media").NaturalDuration.HasTimeSpan,kind+" decodes fixture");var state=Field<object>(form,"seeking");var media=Field<Media>(form,"media");var play=Field<Button>(form,"play");var loop=Field<CheckBox>(form,"loop");var slider=Field<Control>(form,kind=="Capture"?"seek":"slider");Check(!loop.Checked,kind+" loop defaults off");NearEnd(slider);await Until(()=>Field<bool>(state,"Ended"),kind+" reaches natural end");Check(play.Text=="Replay"&&!Field<bool>(state,"Playing"),kind+" end changes main button to Replay");play.PerformClick();await Task.Delay(900);Check(media.Position.TotalSeconds>.05&&media.Position.TotalSeconds<2&&Field<bool>(state,"Playing")&&play.Text=="Pause",kind+" main button replays from beginning");play.PerformClick();double at=media.Position.TotalSeconds;await Task.Delay(250);Check(!Field<bool>(state,"Playing")&&play.Text=="Play"&&Math.Abs(media.Position.TotalSeconds-at)<.08,kind+" Pause still pauses after replay");loop.Checked=true;play.PerformClick();NearEnd(slider);await Task.Delay(1700);Check(Field<bool>(state,"Playing")&&!Field<bool>(state,"Pending")&&!Field<bool>(state,"Ended")&&media.Position.TotalSeconds<2&&play.Text=="Pause",kind+" checked Loop automatically plays again");loop.Checked=false;NearEnd(slider);await Until(()=>Field<bool>(state,"Ended"),kind+" turning Loop off stops at next end");Check(play.Text=="Replay",kind+" completed clip never retains Pause label");form.Close();}
 [STAThread]static void Main(string[] args){string clip=Path.GetFullPath(args[0]),outdir=Path.GetFullPath(args[1]);Directory.CreateDirectory(outdir);preview=Assembly.LoadFrom(Path.GetFullPath(args[2]));Set("File",clip);Set("Check",outdir);Application.EnableVisualStyles();var driver=new Form{ShowInTaskbar=false,WindowState=FormWindowState.Minimized};driver.Shown+=async(s,e)=>{try{using(var capture=Capture())await Exercise(capture,"Capture");using(var quick=Quick(clip)){quick.GetType().GetField("userMute",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(quick,true);await Exercise(quick,"Quick");}File.WriteAllText(Path.Combine(outdir,"loop-result.json"),"{\"ok\":true,\"checks\":"+checks+"}");}catch(Exception error){File.WriteAllText(Path.Combine(outdir,"loop-result.json"),new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(new{ok=false,error=error.ToString(),checks=checks}));}finally{driver.Close();}};Application.Run(driver);}
}
